using System.ComponentModel.DataAnnotations;using EddaStore.Models.Identity;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.AspNetCore.RateLimiting;
namespace EddaStore.Areas.Identity.Pages.Account;
[EnableRateLimiting("auth")]
public class RegisterModel(UserManager<ApplicationUser> userManager):PageModel{[BindProperty]public InputModel Input{get;set;}=new();public class InputModel{[Required,EmailAddress,Display(Name="البريد الإلكتروني")]public string Email{get;set;}="";[Required,DataType(DataType.Password),StringLength(100,MinimumLength=8),Display(Name="كلمة المرور")]public string Password{get;set;}="";[Required,DataType(DataType.Password),Compare(nameof(Password),ErrorMessage="كلمتا المرور غير متطابقتين."),Display(Name="تأكيد كلمة المرور")]public string ConfirmPassword{get;set;}="";public string? ReturnUrl{get;set;}}public void OnGet(string? returnUrl=null)=>Input.ReturnUrl=returnUrl;public async Task<IActionResult>OnPostAsync(){if(!ModelState.IsValid)return Page();var user=new ApplicationUser{UserName=Input.Email,Email=Input.Email};var result=await userManager.CreateAsync(user,Input.Password);if(result.Succeeded)return RedirectToPage("RegistrationConfirmation");foreach(var e in result.Errors)ModelState.AddModelError(string.Empty,e.Description);return Page();}}
